-- ---------- Doğrulama: beklenen  yabanci_anahtar = 101 | sahipsiz_madde = 0 ----------
SELECT (SELECT COUNT(*) FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA = 'u2858154_mehse') AS yabanci_anahtar,
       (SELECT COUNT(*) FROM `u2858154_mehse`.risk_maddeleri m WHERE NOT EXISTS (SELECT 1 FROM `u2858154_mehse`.risk_degerlendirmeleri r WHERE r.id = m.risk_degerlendirmesi_id)) AS sahipsiz_madde;
